import "core-js/modules/es.array.push.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import DeleteRfid from "@/components/PresenceApp/PopUps/DeleteRfid.vue";
import AddRfid from "@/components/PresenceApp/PopUps/AddRfid.vue";
import EditRfid from "@/components/PresenceApp/PopUps/EditRfid.vue";
import SnackBar from "@/components/SnackBar.vue";
import { list_rfid_mapped_locations } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    AddRfid,
    EditRfid,
    DeleteRfid
  },
  data() {
    return {
      headers: [{
        title: "Location",
        value: "location_name",
        sortable: false
      }, {
        title: "Box ID",
        value: "box_id",
        sortable: false
      }, {
        title: "Action",
        value: "actions",
        sortable: false
      }],
      tableData: [],
      tableLoading: false,
      rfidCreation: false,
      rfidEdition: false,
      rfidDeletion: false,
      next_token: null,
      componentCheck: 0,
      rowInfo: {},
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      search: "",
      fixed: true,
      height: 0,
      sortedAndPaginatedItems: [],
      page: 1,
      itemsPerPage: 100,
      currentPage: 1,
      totalCount: 0,
      pageCount: 0
    };
  },
  computed: {
    pageCount() {
      return Math.ceil(this.totalCount / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  created() {
    this.height = window.innerHeight - 260;
  },
  watch: {},
  mounted() {
    this.CommonVuetifyObj = useDisplay();
    this.fetch_rfid();
  },
  methods: {
    add_action() {
      this.componentCheck = 1;
      this.rfidCreation = true;
    },
    edit_Rfid(item) {
      this.componentCheck = 2;
      this.rfidEdition = true;
      this.rowInfo = item;
    },
    delete_Rfid(item) {
      this.componentCheck = 3;
      this.rfidDeletion = true;
      this.rowInfo = item;
    },
    async fetch_rfid() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_rfid_mapped_locations, {}));
        this.tableLoading = false;
        this.tableData = [];
        let response = JSON.parse(result.data.list_rfid_mapped_locations);
        this.tableData = Array.isArray(response.data) ? response.data : [];
        this.totalCount = this.tableData.length;
        this.sortedAndPaginatedItems = this.tableData;
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.rfidCreation = false;
      this.rfidEdition = false;
      this.rfidDeletion = false;
      this.fetch_rfid();
    },
    handleSortChange(newSortBy) {
      // Implement the logic to handle sort change
    }
  }
};
